/*
 * ADR 0010 D10 cross-check: a descriptor GENERATED by tools/mkimage.py must pass the
 * REAL kernel validator (kernel/core/vm.c je_vm_image_validate), and simple
 * mutations of it must fail. This ties the Python tool's rules (E1-E10) to the C
 * rules (ADR 0007 D8), so a drift in either one shows up here.
 *
 * Written from the frozen mkimage.py SPEC docstring and include/jeios/{vm,image}.h,
 * not from the tool's implementation.
 *
 * Build (hosted):
 *   gcc -Iinclude -std=c11 ... \
 *       -DJE_TEST_IMAGE_C='"build/0/gen/image_c_hello.c"' -DJE_TEST_IMAGE_NAME=c_hello \
 *       tests/test_image.c kernel/core/vm.c kernel/core/alloc.c kernel/core/boot.c \
 *       kernel/core/handle.c
 * The generated source is #included into THIS translation unit, after
 * <jeios/image.h>. For c_hello the compiler therefore also checks that the
 * generated definitions match image.h's extern declarations, and sizeof(blob) is
 * known so it can be compared with je_img_<name>_len.
 *
 * Checks use CHECK (not assert) so they survive -DNDEBUG (JCS-05).
 */
#include <jeios/image.h>
#include <jeios/vm.h>
#include <stdbool.h>
#include <stdio.h>
#include <string.h>

#ifndef JE_TEST_IMAGE_C
#error "define JE_TEST_IMAGE_C as the quoted path of a mkimage.py-generated .c file"
#endif
#ifndef JE_TEST_IMAGE_NAME
#define JE_TEST_IMAGE_NAME c_hello
#endif

#include JE_TEST_IMAGE_C

#define JE_CAT3_(a, b, c) a##b##c
#define JE_CAT3(a, b, c)  JE_CAT3_(a, b, c)
#define JE_STR_(x)        #x
#define JE_STR(x)         JE_STR_(x)
#define IMG_BLOB JE_CAT3(je_img_, JE_TEST_IMAGE_NAME, _blob)
#define IMG_LEN  JE_CAT3(je_img_, JE_TEST_IMAGE_NAME, _len)
#define IMG_DESC JE_CAT3(je_img_, JE_TEST_IMAGE_NAME, _desc)

static unsigned g_checks;
static unsigned g_failures;

#define CHECK(cond, what)                                                        \
    do {                                                                         \
        ++g_checks;                                                              \
        if (!(cond)) {                                                           \
            ++g_failures;                                                        \
            fprintf(stderr, "test_image: FAIL %s:%d: %s [%s]\n", __FILE__,       \
                    __LINE__, (what), #cond);                                    \
        }                                                                        \
    } while (0)

static je_status validate(const je_vm_image *img, size_t blob_len)
{
    return je_vm_image_validate(img, blob_len);
}

/* Index of the first R|X segment, or segment_count if there is none. */
static uint32_t first_rx(const je_vm_image *img)
{
    for (uint32_t s = 0; s < img->segment_count; ++s)
        if (img->segments[s].perm == (JE_VM_R | JE_VM_X)) return s;
    return img->segment_count;
}

/* True if `off` lies in the initialized bytes of some R|X segment other than `skip`. */
static bool entry_covered_elsewhere(const je_vm_image *img, uint64_t off, uint32_t skip)
{
    for (uint32_t s = 0; s < img->segment_count; ++s) {
        const je_vm_segment *g = &img->segments[s];
        if (s == skip || g->perm != (JE_VM_R | JE_VM_X)) continue;
        if (off >= g->target_offset && off - g->target_offset < g->source_size) return true;
    }
    return false;
}

/* The generated descriptor itself: validator + the tool's own output promises. */
static void check_generated(const je_vm_image *d, size_t len)
{
    static const je_vm_segment zero_seg;

    CHECK(sizeof IMG_BLOB == len, "sizeof blob == je_img_<name>_len");
    CHECK(validate(d, len) == JE_OK, "generated descriptor validates (JE_OK)");

    CHECK(d->version == JE_VM_IMAGE_VERSION, "version 1");
    CHECK(d->reserved == 0u, "descriptor reserved 0");
    CHECK(d->segment_count >= 1u && d->segment_count <= JE_VM_MAX_SEGMENTS, "segment_count 1..8");
    if (d->segment_count < 1u || d->segment_count > JE_VM_MAX_SEGMENTS) return;

    uint64_t running = 0;
    for (uint32_t s = 0; s < d->segment_count; ++s) {
        const je_vm_segment *g = &d->segments[s];
        CHECK(g->reserved == 0u, "segment reserved 0");
        CHECK(g->source_offset == running, "source_offset is the running blob offset");
        CHECK((g->memory_size & (JE_PAGE_SIZE - 1u)) == 0u, "memory_size page-rounded");
        CHECK(g->perm == (JE_VM_R | JE_VM_X) || g->perm == JE_VM_R ||
                  g->perm == (JE_VM_R | JE_VM_W),
              "perm is exactly R|X, R or R|W");
        if (s > 0)
            CHECK(g->target_offset > d->segments[s - 1].target_offset,
                  "segments in ascending target_offset (vaddr) order");
        running += g->source_size;
    }
    CHECK(running == len, "blob length == sum of source_size (concatenation)");

    /* Independent content pin: a structurally valid descriptor whose blob was
     * zeroed (or otherwise degenerate) would still validate, because the
     * validator does not inspect blob bytes. Guard against that class of
     * wrong-but-valid artifact: the entry's RX segment must carry real code, so
     * its initialized bytes cannot be all-zero (x86-64 all-zero decodes to
     * `add [rax],al` and would never be a sane entry). This is a weak but
     * genuinely independent oracle over the embedded c_hello image. */
    {
        const uint32_t rx = first_rx(d);
        if (rx < d->segment_count) {
            const je_vm_segment *g = &d->segments[rx];
            int any_nonzero = 0;
            for (uint64_t i = 0; i < g->source_size; ++i)
                if (IMG_BLOB[g->source_offset + i] != 0u) { any_nonzero = 1; break; }
            CHECK(g->source_size == 0u || any_nonzero,
                  "entry RX segment blob bytes are not all zero (non-degenerate image)");
            /* The entry offset must land on an actual byte within that code. */
            if (g->source_size > 0u)
                CHECK(d->entry_offset >= g->target_offset &&
                          d->entry_offset < g->target_offset + g->source_size,
                      "entry lands inside the RX segment's initialized bytes");
        }
    }

    for (uint32_t s = d->segment_count; s < JE_VM_MAX_SEGMENTS; ++s)
        CHECK(memcmp(&d->segments[s], &zero_seg, sizeof zero_seg) == 0, "unused slot all zero");

    /* The blob ends exactly where the last segment's bytes end, so a blob one
     * byte short must fail (only meaningful when the last segment has bytes). */
    const je_vm_segment *last = &d->segments[d->segment_count - 1u];
    if (len > 0u && last->source_size > 0u)
        CHECK(validate(d, len - 1u) != JE_OK, "blob_len - 1 rejected");
}

/* Mutations: each starts from a fresh copy; each must be rejected by the C validator. */
static void check_mutations(const je_vm_image *d, size_t len)
{
    je_vm_image m;
    const uint32_t n = d->segment_count;
    if (n < 1u || n > JE_VM_MAX_SEGMENTS) return;   /* already reported */
    const uint32_t rx = first_rx(d);
    CHECK(rx < n, "image has an R|X segment");
    if (rx >= n) return;

    /* Harness control: an unmodified copy still validates. */
    m = *d;
    CHECK(validate(&m, len) == JE_OK, "control: unmodified copy validates");

    /* Illegal permission on every segment, including W|X and R|W|X. */
    static const uint32_t bad_perm[] = {
        0u, JE_VM_W, JE_VM_X, JE_VM_W | JE_VM_X, JE_VM_R | JE_VM_W | JE_VM_X, 0x8u,
        JE_VM_R | 0x8u, JE_VM_R | JE_VM_X | 0x80000000u,
    };
    for (uint32_t s = 0; s < n; ++s) {
        for (size_t k = 0; k < sizeof bad_perm / sizeof bad_perm[0]; ++k) {
            m = *d;
            m.segments[s].perm = bad_perm[k];
            CHECK(validate(&m, len) != JE_OK, "illegal perm rejected");
        }
    }

    /* Entry: last initialized code byte is legal (boundary control) ... */
    const je_vm_segment *code = &d->segments[rx];
    if (code->source_size > 0u) {
        m = *d;
        m.entry_offset = code->target_offset + code->source_size - 1u;
        CHECK(validate(&m, len) == JE_OK, "entry at last initialized RX byte validates");
    }
    /* ... the first byte after the initialized bytes (BSS or beyond) is not. */
    m = *d;
    m.entry_offset = code->target_offset + code->source_size;
    if (!entry_covered_elsewhere(&m, m.entry_offset, rx))
        CHECK(validate(&m, len) != JE_OK, "entry just past RX initialized bytes rejected");
    /* Entry inside every non-X segment (its first byte, and its BSS if any). */
    for (uint32_t s = 0; s < n; ++s) {
        const je_vm_segment *g = &d->segments[s];
        if (g->perm == (JE_VM_R | JE_VM_X)) continue;
        m = *d;
        m.entry_offset = g->target_offset;
        CHECK(validate(&m, len) != JE_OK, "entry in a non-X segment rejected");
        if (g->memory_size > g->source_size) {
            m.entry_offset = g->target_offset + g->source_size;
            CHECK(validate(&m, len) != JE_OK, "entry in a non-X segment's BSS rejected");
        }
    }
    /* Make the code segment's tail BSS-like by shrinking its initialized size to 0
     * (blob bounds stay legal): the original entry is then in BSS. */
    m = *d;
    m.segments[rx].source_size = 0u;
    if (!entry_covered_elsewhere(&m, m.entry_offset, rx))
        CHECK(validate(&m, len) != JE_OK, "entry in RX BSS (source_size 0) rejected");
    m = *d;
    m.entry_offset = JE_VM_ARENA_SIZE;
    CHECK(validate(&m, len) != JE_OK, "entry outside the arena rejected");

    /* Overlap: two segments on the same page. */
    if (n >= 2u) {
        m = *d;
        m.segments[1].target_offset = m.segments[0].target_offset;
        CHECK(validate(&m, len) != JE_OK, "overlap (seg1 onto seg0) rejected");
        m = *d;
        m.segments[0].memory_size = m.segments[1].target_offset - m.segments[0].target_offset +
                                    JE_PAGE_SIZE;
        CHECK(validate(&m, len) != JE_OK, "overlap (seg0 grown into seg1) rejected");
    }
    if (n < JE_VM_MAX_SEGMENTS) {
        m = *d;
        m.segments[n] = m.segments[rx];   /* duplicate the code segment */
        m.segment_count = n + 1u;
        CHECK(validate(&m, len) != JE_OK, "overlap (duplicated segment) rejected");
    }

    /* Guard page and stack intrusion by the highest segment. */
    const uint32_t hi = n - 1u;
    const uint64_t hi_pages = d->segments[hi].memory_size;
    if (hi_pages <= JE_VM_GUARD_OFFSET) {
        m = *d;
        m.segments[hi].target_offset = JE_VM_GUARD_OFFSET - hi_pages + JE_PAGE_SIZE;
        CHECK(validate(&m, len) != JE_OK, "segment into the guard page rejected");
    }
    m = *d;
    m.segments[hi].target_offset = JE_VM_STACK_OFFSET;
    CHECK(validate(&m, len) != JE_OK, "segment onto the stack rejected");
    m = *d;
    m.segments[hi].target_offset = JE_VM_ARENA_SIZE;
    CHECK(validate(&m, len) != JE_OK, "segment beyond the arena rejected");

    /* Page budget: grow the highest segment so image + stack pages exceed 64. */
    uint64_t pages = 0;
    for (uint32_t s = 0; s < n; ++s) pages += d->segments[s].memory_size / JE_PAGE_SIZE;
    if (pages <= JE_VM_MAX_USER_PAGES - JE_VM_STACK_PAGES) {
        m = *d;
        m.segments[hi].memory_size +=
            (JE_VM_MAX_USER_PAGES - JE_VM_STACK_PAGES - pages + 1u) * JE_PAGE_SIZE;
        CHECK(validate(&m, len) != JE_OK, "page budget 65 rejected");
    }

    /* Layout / header fields. */
    m = *d; m.version = 2u;
    CHECK(validate(&m, len) == JE_ERR_UNSUPPORTED, "version 2 -> JE_ERR_UNSUPPORTED");
    m = *d; m.reserved = 1u;
    CHECK(validate(&m, len) != JE_OK, "descriptor reserved != 0 rejected");
    m = *d; m.segment_count = 0u;
    CHECK(validate(&m, len) != JE_OK, "segment_count 0 rejected");
    m = *d; m.segment_count = JE_VM_MAX_SEGMENTS + 1u;
    CHECK(validate(&m, len) != JE_OK, "segment_count 9 rejected");

    /* Per-segment field mutations applied to EVERY segment, not just seg 0: a
     * validator that only checks reserved/alignment/source bounds for segment 0
     * (or stops early) must be caught on segments 1..n-1 too. */
    for (uint32_t s = 0; s < n; ++s) {
        m = *d; m.segments[s].reserved = 1u;
        CHECK(validate(&m, len) != JE_OK, "segment reserved != 0 rejected (any seg)");
        m = *d; m.segments[s].memory_size += 1u;
        CHECK(validate(&m, len) != JE_OK, "unaligned memory_size rejected (any seg)");
        m = *d; m.segments[s].target_offset += 1u;
        CHECK(validate(&m, len) != JE_OK, "unaligned target_offset rejected (any seg)");
        m = *d; m.segments[s].source_size = m.segments[s].memory_size + 1u;
        CHECK(validate(&m, len) != JE_OK, "source_size > memory_size rejected (any seg)");
        m = *d; m.segments[s].source_offset = (uint64_t)len + 1u;
        CHECK(validate(&m, len) != JE_OK, "source_offset beyond blob rejected (any seg)");
    }
}

int main(void)
{
    const je_vm_image *d = &IMG_DESC;
    const size_t len = (size_t)IMG_LEN;

    check_generated(d, len);
    check_mutations(d, len);

    if (g_failures != 0u) {
        fprintf(stderr, "test_image: FAIL (%u of %u checks) image=%s\n", g_failures, g_checks,
                JE_STR(JE_TEST_IMAGE_NAME));
        return 1;
    }
    printf("test_image: PASS (%u checks) image=%s blob=%zu segments=%u\n", g_checks,
           JE_STR(JE_TEST_IMAGE_NAME), len, (unsigned)d->segment_count);
    return 0;
}
